CREATE TABLE pms_affiliate_profile (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),active BIT NOT NULL,created_by BIGINT,last_modified_date DATETIME(6),user_id BIGINT NOT NULL,referral_code VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,commission_rate DECIMAL(8,2) NOT NULL,minimum_payout DECIMAL(15,2) NOT NULL,currency VARCHAR(3) NOT NULL,payout_account_id BIGINT NULL,PRIMARY KEY(id),UNIQUE KEY uk_affiliate_uuid(uuid),UNIQUE KEY idx_affiliate_user(user_id),UNIQUE KEY idx_affiliate_code(referral_code),CONSTRAINT fk_affiliate_user FOREIGN KEY(user_id) REFERENCES pms_users(id),CONSTRAINT fk_affiliate_account FOREIGN KEY(payout_account_id) REFERENCES pms_payment_account(id));
CREATE TABLE pms_affiliate_referral (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),active BIT NOT NULL,created_by BIGINT,last_modified_date DATETIME(6),affiliate_user_id BIGINT NOT NULL,referred_user_id BIGINT NOT NULL,referral_code VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,campaign VARCHAR(100),registered_at DATETIME(6),converted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_referral_uuid(uuid),UNIQUE KEY idx_referral_referred(referred_user_id),KEY idx_referral_affiliate(affiliate_user_id,status),CONSTRAINT fk_referral_affiliate FOREIGN KEY(affiliate_user_id) REFERENCES pms_users(id),CONSTRAINT fk_referral_user FOREIGN KEY(referred_user_id) REFERENCES pms_users(id));
CREATE TABLE pms_affiliate_payout (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),active BIT NOT NULL,created_by BIGINT,last_modified_date DATETIME(6),payout_number VARCHAR(30) NOT NULL,affiliate_user_id BIGINT NOT NULL,payment_account_id BIGINT NOT NULL,amount DECIMAL(15,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(30) NOT NULL,requested_at DATETIME(6),processed_at DATETIME(6),payment_reference VARCHAR(100),notes VARCHAR(1000),PRIMARY KEY(id),UNIQUE KEY uk_payout_uuid(uuid),UNIQUE KEY uk_payout_number(payout_number),KEY idx_payout_affiliate(affiliate_user_id,status),CONSTRAINT fk_payout_affiliate FOREIGN KEY(affiliate_user_id) REFERENCES pms_users(id),CONSTRAINT fk_payout_account FOREIGN KEY(payment_account_id) REFERENCES pms_payment_account(id));
CREATE TABLE pms_affiliate_commission (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),active BIT NOT NULL,created_by BIGINT,last_modified_date DATETIME(6),affiliate_user_id BIGINT NOT NULL,referred_user_id BIGINT NOT NULL,invoice_id BIGINT NOT NULL,invoice_ref VARCHAR(100) NOT NULL,qualifying_amount DECIMAL(15,2) NOT NULL,commission_rate DECIMAL(8,2) NOT NULL,commission_amount DECIMAL(15,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(30) NOT NULL,provider_reference VARCHAR(100),earned_at DATETIME(6),payout_id BIGINT NULL,PRIMARY KEY(id),UNIQUE KEY uk_commission_uuid(uuid),UNIQUE KEY idx_commission_invoice(invoice_id),KEY idx_commission_affiliate(affiliate_user_id,status),CONSTRAINT fk_commission_affiliate FOREIGN KEY(affiliate_user_id) REFERENCES pms_users(id),CONSTRAINT fk_commission_referred FOREIGN KEY(referred_user_id) REFERENCES pms_users(id),CONSTRAINT fk_commission_invoice FOREIGN KEY(invoice_id) REFERENCES pms_invoice(id),CONSTRAINT fk_commission_payout FOREIGN KEY(payout_id) REFERENCES pms_affiliate_payout(id));
